UPDATE ticket_stock SET available_stock = available_stock - CASE ticket_category_id
WHEN #{item.ticketCategoryId} THEN #{item.quantity}
ELSE 0 END, locked_stock = locked_stock + CASE ticket_category_id
WHEN #{item.ticketCategoryId} THEN #{item.quantity}
ELSE 0 END, version = version + 1, updated_at = NOW() WHERE ticket_category_id IN
#{item.ticketCategoryId}
AND available_stock >= CASE ticket_category_id
WHEN #{item.ticketCategoryId} THEN #{item.quantity}
ELSE 0 END
